#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT 1024          /* 0x3ff + 1, as in the original binary */
#define OUT_BUF   2048          /* more than enough for the worst case */

static char out_buf[OUT_BUF];

static void do_escape(const char *src)
{
    size_t i, out = 0;
    for (i = 0; src[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)src[i];
        switch (c) {
            case '\\':
                out_buf[out++] = '\\';
                out_buf[out++] = '\\';
                break;
            case '"':
                out_buf[out++] = '\\';
                out_buf[out++] = '"';
                break;
            case '\n':
                out_buf[out++] = '\\';
                out_buf[out++] = 'n';
                break;
            case '\t':
                out_buf[out++] = '\\';
                out_buf[out++] = 't';
                break;
            default:
                out_buf[out++] = c;
                break;
        }
    }
    out_buf[out] = '\0';
    puts(out_buf);
}

static void do_unescape(const char *src)
{
    size_t i, out = 0;
    for (i = 0; src[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)src[i];
        if (c != '\\') {
            out_buf[out++] = c;
            continue;
        }
        ++i; /* look at the character after the backslash */
        if (src[i] == '\0') {               /* trailing backslash -> error */
            puts("INVALID");
            return;
        }
        switch ((unsigned char)src[i]) {
            case '\\':
                out_buf[out++] = '\\';
                break;
            case '"':
                out_buf[out++] = '"';
                break;
            case 'n':
                out_buf[out++] = '\n';
                break;
            case 't':
                out_buf[out++] = '\t';
                break;
            default:
                puts("INVALID");
                return;
        }
    }
    out_buf[out] = '\0';
    puts(out_buf);
}

int main(int argc, char *argv[])
{
    const char *mode;
    const char *input;

    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    mode  = argv[1];
    input = argv[2];

    if (strlen(input) > MAX_INPUT) {
        puts("USAGE");
        return 0;
    }

    if (strcmp(mode, "escape") == 0) {
        do_escape(input);
    } else if (strcmp(mode, "unescape") == 0) {
        do_unescape(input);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
